"""Seat students in rows, ordered by last name."""

from typing import List, Sequence

from rosterkit.models import Student

def _sort_key(student: Student) -> tuple:
    family = student.last_name.lower()
    return (family, student.first_name.lower())

def _ordered(
    students: Sequence[Student],
    seats: int,
) -> list:
    if seats <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")
    return sorted(students, key=_sort_key)

def _chunks(items: list, size: int) -> List[list]:
    return [
        items[start:start + size]
        for start in range(0, len(items), size)
    ]

def _row_line(number: int, group: list) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"

# ---
def seat_rows(
    students: Sequence[Student],
    seats: int,
) -> List[str]:
    """One line of text per row of seats."""
    groups = _chunks(_ordered(students, seats), seats)
    return [
        _row_line(index, group)
        for index, group in enumerate(groups, 1)
    ]

after.tests/test_seating.py:
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

def make_student(family, given):
    return Student("id", family, given, "A")

def make_class():
    return [
        make_student("Halloway", "Juno"),
        make_student("Dunmere", "Piet"),
        make_student("Anders", "Kai"),
    ]

class SeatRowsTests(unittest.TestCase):
    # ---
    def test_sorts_by_last_name_and_fills_rows(self):
        rows = seat_rows(make_class(), 2)
        self.assertEqual(
            rows,
            [
                "Row 1: Anders, Kai | Dunmere, Piet",
                "Row 2: Halloway, Juno",
            ],
        )

    # ---
    def test_one_row_when_seats_exceed_students(self):
        rows = seat_rows(make_class(), 10)
        self.assertEqual(len(rows), 1)

    # ---
    def test_ties_break_on_first_name(self):
        pair = [
            make_student("Lee", "Zoe"),
            make_student("lee", "Amy"),
        ]
        self.assertEqual(
            seat_rows(pair, 2),
            ["Row 1: lee, Amy | Lee, Zoe"],
        )

    # ---
    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(make_class(), 0)

    # ---
    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(make_class(), -3)

    # ---
    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 4)

    # ---
    def test_input_is_not_reordered(self):
        roster = make_class()
        seat_rows(roster, 2)
        self.assertEqual(roster[0].last_name, "Halloway")
